#include <fstream>
#include <vector>
#include <algorithm>
using namespace std;
int main(){
    ifstream in("herding.in");ofstream out("herding.out");
    int n;in>>n;vector<long long> x(n);for(auto &v:x)in>>v;
    sort(x.begin(),x.end());
    int minimum=n,best=0,left=0;
    for(int right=0;right<n;right++){
        while(x[right]-x[left]>=n)++left;
        best=max(best,right-left+1);
    }
    minimum=n-best;
    if((x[n-2]-x[0]==n-2&&x[n-1]-x[n-2]>2)||
       (x[n-1]-x[1]==n-2&&x[1]-x[0]>2))minimum=2;
    long long maximum=max(x[n-2]-x[0],x[n-1]-x[1])-(n-2);
    out<<minimum<<'\n'<<maximum<<'\n';
}
