#include <fstream>
using namespace std;
int difference[1001][1001];
int main(){
    ifstream in("paintbarn.in");ofstream out("paintbarn.out");
    int n,k;in>>n>>k;
    for(int i=0;i<n;i++){
        int a,b,c,d;in>>a>>b>>c>>d;
        ++difference[a][b];--difference[a][d];
        --difference[c][b];++difference[c][d];
    }
    int area=0;
    for(int x=0;x<1000;x++)for(int y=0;y<1000;y++){
        if(x)difference[x][y]+=difference[x-1][y];
        if(y)difference[x][y]+=difference[x][y-1];
        if(x&&y)difference[x][y]-=difference[x-1][y-1];
        if(difference[x][y]==k)++area;
    }
    out<<area<<'\n';
}
