#include <fstream>
#include <vector>
#include <utility>
#include <string>
using namespace std;
int main(){
    ifstream in("revegetate.in");ofstream out("revegetate.out");
    int n,m;in>>n>>m;vector<vector<pair<int,int>>> graph(n);
    for(int i=0;i<m;i++){
        char kind;int a,b;in>>kind>>a>>b;--a;--b;
        int parity=(kind=='D');graph[a].push_back({b,parity});graph[b].push_back({a,parity});
    }
    vector<int> color(n,-1);int components=0;
    for(int root=0;root<n;root++)if(color[root]==-1){
        ++components;color[root]=0;vector<int> stack(1,root);
        while(!stack.empty()){
            int u=stack.back();stack.pop_back();
            for(auto [v,parity]:graph[u]){
                int required=color[u]^parity;
                if(color[v]==-1){color[v]=required;stack.push_back(v);}
                else if(color[v]!=required){out<<"0\n";return 0;}
            }
        }
    }
    out<<'1'<<string(components,'0')<<'\n';
}
